import{_ as a,o as t,c as i,a0 as o}from"./chunks/framework.Bmhw_dvp.js";const p=JSON.parse('{"title":"Voice & Cast","description":"TTS engine details, audio synchronization, and character maps.","frontmatter":{"isInternal":true,"type":"Specification","title":"Voice & Cast","description":"TTS engine details, audio synchronization, and character maps.","tags":["features","specs","architecture"]},"headers":[],"relativePath":"specs/features/voice_and_cast.md","filePath":"specs/features/voice_and_cast.md"}'),r={name:"specs/features/voice_and_cast.md"};function n(c,e,s,l,d,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="voice-cast-technical-specification" tabindex="-1">Voice &amp; Cast Technical Specification <a class="header-anchor" href="#voice-cast-technical-specification" aria-label="Permalink to &quot;Voice &amp; Cast Technical Specification&quot;">​</a></h1><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>The Cast Manager handles assigning unique Text-to-Speech (TTS) voices to different speakers in a script, supporting multi-character dialogue.</p><h2 id="_2-tts-engines-supported" tabindex="-1">2. TTS Engines Supported <a class="header-anchor" href="#_2-tts-engines-supported" aria-label="Permalink to &quot;2. TTS Engines Supported&quot;">​</a></h2><ul><li><strong>Google Cloud TTS</strong>: Standard, WaveNet, Neural2, Journey, and Polyglot models.</li><li><strong>Gemini Audio</strong>: Advanced expressive voices (if supported by the API).</li></ul><h2 id="_3-character-map" tabindex="-1">3. Character Map <a class="header-anchor" href="#_3-character-map" aria-label="Permalink to &quot;3. Character Map&quot;">​</a></h2><ul><li>A project-level object stored in Firestore: <code>projectData.characterMap</code>.</li><li><strong>Structure</strong>: <code>{ [characterName: string]: { voiceId: string, pitch: number, speed: number, language: string } }</code></li><li>Users can assign lines in the script to specific characters using the Timeline UI.</li></ul><h2 id="_4-audio-synchronization" tabindex="-1">4. Audio Synchronization <a class="header-anchor" href="#_4-audio-synchronization" aria-label="Permalink to &quot;4. Audio Synchronization&quot;">​</a></h2><ul><li>The <code>useAudioSync</code> hook ties a hidden <code>&lt;audio&gt;</code> element to the Timeline component.</li><li>As the audio plays, <code>timeupdate</code> events check the <code>timeline</code> array to determine which scene is currently active, highlighting it in the UI and automatically paginating the Visual Stage.</li></ul><h2 id="_5-audio-generation-architecture" tabindex="-1">5. Audio Generation Architecture <a class="header-anchor" href="#_5-audio-generation-architecture" aria-label="Permalink to &quot;5. Audio Generation Architecture&quot;">​</a></h2><ul><li><strong>Parallel Batching</strong>: Instead of generating audio sequentially, the backend generator agent groups script lines by character (<code>speaker</code>).</li><li><strong>Concurrent Execution</strong>: Within each character group, lines are processed in parallel batches (e.g., chunks of 5) using <code>Promise.all</code> with a delay to mitigate API rate limits.</li><li><strong>Chronological Preservation</strong>: Because chunks are processed out of order, the <code>audioUrls</code> array is pre-allocated. Resulting audio paths are mapped back to their absolute index to guarantee perfect chronological synchronization for the ffmpeg aggregator.</li></ul>',11)])])}const g=a(r,[["render",n]]);export{p as __pageData,g as default};
